import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SimulationType{SimulationType: 1}
EDITOR = bytes.fromhex("01")

GOLDENS = [pytest.param(v2225.SimulationTypePacket(sim_type=v2225.SimulationType.EDITOR), EDITOR, id="editor")]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_simulation_type_is_packet_168(version):
    assert version.PACKETS[168] is version.SimulationTypePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_simulation_type_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_simulation_type_decodes_from_its_golden(packet, golden):
    assert v2225.SimulationTypePacket.from_bytes(golden) == packet


def test_simulation_type_body_is_one_byte():
    assert len(bytes(v2225.SimulationTypePacket(sim_type=v2225.SimulationType.INVALID))) == 1


def test_simulation_type_rejects_an_empty_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.SimulationTypePacket.from_bytes(b"")
